// Extract and normalize the fields the rest of the workflow needs.
// patients.whatsapp_phone has CHECK (whatsapp_phone ~ '^\+[1-9][0-9]{6,14}$'),
// i.e. E.164 with a leading '+' and no other punctuation. WhatsApp's
// "from" field arrives as digits only (e.g. "919876543210"), so we add
// the '+' and strip anything that is not a digit before it.
const msg = $json.messages[0];
const rawFrom = String(msg.from || '').trim();
const digitsOnly = rawFrom.replace(/[^0-9]/g, '');
const normalizedPhone = '+' + digitsOnly;

const phonePattern = /^\+[1-9][0-9]{6,14}$/;
if (!phonePattern.test(normalizedPhone)) {
  throw new Error('Could not normalize WhatsApp sender number into the expected +<countrycode><number> format required by the database.');
}

return [{
  json: {
    normalized_phone: normalizedPhone,
    wa_message_id: msg.id,
    message_text: msg.text?.body || '',
    wa_timestamp: msg.timestamp,
    phone_number_id: $json.metadata?.phone_number_id || '',
  }
}];

// Mirrors Normalize Message's phone normalization exactly, but does not
// require msg.text (this branch handles voice/image/document/etc, which
// have no text body). Used only to identify the sender/idempotency key so
// we can deduplicate and send a single "text only" reply.
const msg = $json.messages[0];
const rawFrom = String(msg.from || '').trim();
const digitsOnly = rawFrom.replace(/[^0-9]/g, '');
const normalizedPhone = '+' + digitsOnly;

const phonePattern = /^\+[1-9][0-9]{6,14}$/;
if (!phonePattern.test(normalizedPhone)) {
  throw new Error('Could not normalize WhatsApp sender number into the expected +<countrycode><number> format required by the database.');
}

return [{
  json: {
    normalized_phone: normalizedPhone,
    wa_message_id: msg.id,
    message_type: msg.type || 'unknown',
    phone_number_id: $json.metadata?.phone_number_id || '',
  }
}];
